import requests

def test_post_auth_login_returns_data_token():
    base_url = "http://localhost:5169"
    url = f"{base_url}/api/Auth/login"
    payload = {
        "email": "admin@magiccar.com",
        "password": "Admin123!"
    }
    headers = {
        "Content-Type": "application/json"
    }
    timeout = 120

    try:
        response = requests.post(url, json=payload, headers=headers, timeout=timeout)
    except requests.RequestException as e:
        assert False, f"Request to {url} failed with exception: {e}"

    assert response.status_code == 200, f"Expected status code 200 but got {response.status_code}"

    try:
        json_data = response.json()
    except ValueError:
        assert False, "Response is not a valid JSON"

    # Check that success=true if present
    if "success" in json_data:
        assert json_data["success"] is True, f"Expected success=True but got {json_data.get('success')}"
    # Check that 'data' field exists
    assert "data" in json_data, "'data' field missing in response JSON"
    data = json_data["data"]

    # Check token existence under data
    assert "token" in data, "'token' field missing in response['data']"
    token = data["token"]

    # Token should be a non-empty string
    assert isinstance(token, str) and len(token) > 0, "Token must be a non-empty string"

    # Ensure 'accessToken' must NOT be present anywhere in JSON response
    def has_access_token(obj):
        if isinstance(obj, dict):
            for k, v in obj.items():
                if k == "accessToken":
                    return True
                if has_access_token(v):
                    return True
        elif isinstance(obj, list):
            return any(has_access_token(i) for i in obj)
        return False

    assert not has_access_token(json_data), "'accessToken' found in response, but it must be never present"

test_post_auth_login_returns_data_token()

import requests

BASE_URL = "http://localhost:5169"
LOGIN_URL = f"{BASE_URL}/api/Auth/login"
AI_RESOLVE_PART_PRICES_URL = f"{BASE_URL}/api/AI/resolve-part-prices"
TIMEOUT = 120  # seconds

def test_ai_resolve_part_prices():
    # Login as admin to get JWT token
    login_payload = {
        "email": "admin@magiccar.com",
        "password": "Admin123!"
    }
    try:
        login_response = requests.post(LOGIN_URL, json=login_payload, timeout=TIMEOUT)
        assert login_response.status_code == 200, f"Login failed with status {login_response.status_code}"
        login_json = login_response.json()
        assert 'data' in login_json and 'token' in login_json['data'], "Token not found in login response"
        token = login_json['data']['token']
    except Exception as e:
        raise AssertionError(f"Login request failed or invalid response: {e}")

    headers = {
        "Authorization": f"Bearer {token}"
    }

    params = {
        "partName": "filter",
        "partNumber": "OF-1"
    }

    try:
        response = requests.get(AI_RESOLVE_PART_PRICES_URL, headers=headers, params=params, timeout=TIMEOUT)
        assert response.status_code in (200, 400, 404), f"Unexpected status code {response.status_code}"

        if response.status_code == 200:
            # Validate that response JSON is present and is a dict or list (depending on API)
            try:
                resp_json = response.json()
                assert isinstance(resp_json, (dict, list)), "Response JSON is not dict or list for 200 status"
            except Exception as e:
                raise AssertionError(f"Response JSON parsing failed: {e}")
        elif response.status_code == 400:
            # Could be validation error, assert error keys or message present
            try:
                error_json = response.json()
                assert 'errors' in error_json or 'message' in error_json, "Expected error structure missing in 400 response"
            except Exception as e:
                raise AssertionError(f"Error response JSON parsing failed: {e}")
        elif response.status_code == 404:
            # Not found, no body expectations defined
            pass

    except requests.exceptions.Timeout:
        raise AssertionError("Request timed out")
    except requests.exceptions.RequestException as e:
        raise AssertionError(f"Request failed: {e}")

test_ai_resolve_part_prices()

